#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using u64 = unsigned long long;

const ll MOD = 1000000007LL;
const ll INF_LL = (1LL << 28);
const int MAX_D = 100, MAX_K = 40;

ll N;
int K;

vector<vector<ll>> R[MAX_K];
vector<vector<vector<vector<ll>>>> D(MAX_D, vector<vector<vector<ll>>>(MAX_K));

void allocate_matrix(vector<vector<ll>>& A, int rows, int cols) {
    A.assign(rows, vector<ll>(cols, 0LL));
}

vector<vector<ll>> mat_mult(const vector<vector<ll>>& A, const vector<vector<ll>>& B) {
    int n = A.size();
    int m = B.size();
    int p = B[0].size();
    vector<vector<ll>> C(n, vector<ll>(p, 0LL));
    for (int i = 0; i < n; ++i) {
        for (int k = 0; k < m; ++k) {
            if (!A[i][k]) continue;
            for (int j = 0; j < p; ++j) {
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
            }
        }
    }
    return C;
}

void print_matrix(const vector<vector<ll>>& A) {
    for (auto& row : A) {
        for (auto& val : row) {
            cout << val << " ";
        }
        cout << "\n";
    }
    cout << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> K;

    // Convert N to base-K digits
    vector<int> digits;
    ll base = 1;
    while (base <= N) {
        if (base > N / K) break;
        base *= K;
    }
    if (base > N) base /= K;

    ll temp = base;
    while (temp > 0) {
        digits.push_back(N / temp);
        N %= temp;
        temp /= K;
    }
    reverse(digits.begin(), digits.end());

    int cnt = digits.size();

    // Pre-allocate R matrices
    for (int j = 0; j <= K; ++j) {
        R[j] = vector<vector<ll>>(K + 1, vector<ll>(K + 1, 0LL));
    }

    // Pre-allocate D matrices
    for (int i = 0; i <= cnt; ++i) {
        for (int j = 0; j < K; ++j) {
            D[i][j] = vector<vector<ll>>(K + 1, vector<ll>(K + 1, 0LL));
        }
    }

    // Setup R[0], R[1]
    R[0][K][K] = R[1][K][K] = 1;
    for (int j = 0; j < K; ++j) {
        R[0][j][j] = 1;
        R[1][(j + K - 1) % K][j] = 1;
    }

    // Build R[j] for j >= 2
    for (int j = 2; j <= K; ++j) {
        R[j] = mat_mult(R[j - 1], R[1]);
    }

    // Initialize D[0][0]
    for (int j = 0; j <= K; ++j) {
        D[0][0][j][j] = 1;
        D[0][0][j][0] = 1;
    }

    // Build D matrices
    for (int i = 0; i <= cnt; ++i) {
        for (int j = 1; j < K; ++j) {
            vector<vector<ll>> temp1 = mat_mult(R[K - j], D[i][0]);
            vector<vector<ll>> temp2 = mat_mult(temp1, R[j]);
            D[i][j] = mat_mult(D[i][j - 1], temp2);
        }
        if (i < cnt) {
            D[i + 1][0] = D[i][K - 1];
        }
    }

    // Final computation
    vector<vector<ll>> res(1, vector<ll>(K + 1, 0LL));
    res[0][K] = 1;
    int mod_state = 0;

    for (int i = 0; i < cnt; ++i) {
        if (digits[i] != 0) {
            vector<vector<ll>> temp1 = mat_mult(R[K - mod_state], D[cnt - i - 1][digits[i] - 1]);
            vector<vector<ll>> temp2 = mat_mult(temp1, R[mod_state]);
            res = mat_mult(res, temp2);
        }
        mod_state = (mod_state + digits[i]) % K;
    }

    ll ans = 0;
    for (int i = 0; i <= K; ++i) {
        ans = (ans + res[0][i]) % MOD;
    }
    cout << ans << endl;

    return 0;
}
